; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: zxndotl (ZX Spectrum Next - a dot command, Large Model (32K at #8000 + banks, BASIC's screen)), starts in normal mode
; ============================================================

			OUTPUT "VBTEST7.DOT"		; the dot command (C:/DOT/VBTEST7.DOT: .vbtest7 at the BASIC prompt)
; ZX Spectrum Next - a dot command, Large Model (32K at #8000 + banks, BASIC's screen): NTC_ZXNDOT defined, and NTC_ZXNDOTL (the Large Model: the program from #8000, the Memory class's banks from NextZXOS's allocator - asm/ntc_lib_dot.asm)
			DEFINE NTC_ZXNDOT
			DEFINE NTC_ZXNDOTL
			org #2000

; ============================================================
; Platform start code (the platform's ntc_plat_romhead) - at the org, on to ntc_start
; ============================================================
; ------------------------------------------------------------
; The entry (the compiler puts this section first, at #2000) and the
; BASIC-side machinery: everything the ROM calls need, in one place, so
; that the Large Model (zxndotl) - which runs the program from #8000 in its
; own pages and keeps only this 8K in common with BASIC's memory - has it
; here too. Self-contained: no label from another section is named.
; ------------------------------------------------------------
dot_entry:
			di
			ld (dot_bsp), sp		; BASIC's stack: the ROM calls run on it, End returns on it
			ld (dot_hl), hl			; the arguments (0: none)
			ld (dot_bc), bc
			ld a, i
			ld (dot_iold), a		; BASIC's I (put back at the end)
			ld sp, dot_tstack		; a stack of our own for the rest of the entry
			call dot_cmdsave		; the arguments into ntc_cmdbuf before anything moves them
	IFDEF NTC_ZXNDOTL
			call dotl_setup			; the Large Model: its pages, the program read from this file
	ENDIF
			ld hl, dot_chan			; the upper screen is the channel printed to
			call dot_os
			ld a, dot_ivec >> 8		; IM 2, our handler (dot_irq) from here on, except inside dot_os
			ld i, a
			im 2
			jp ntc_start

; dot_cmdsave - (dot_hl) = the arguments: into ntc_cmdbuf, 0 ended, up to 127
; characters, up to #0D, ':' outside double quotes, or 0; leading spaces left out
dot_cmdsave:
			ld hl, (dot_hl)
			ld de, ntc_cmdbuf
			ld a, h
			or l
			jr z, dot_cs_end
			ld b, 127
			ld c, 0					; C = 1 inside quotes
dot_cs_sp:
			ld a, (hl)
			cp ' '
			jr nz, dot_cs_lp
			inc hl
			jr dot_cs_sp
dot_cs_lp:
			ld a, (hl)
			or a
			jr z, dot_cs_end
			cp #0D
			jr z, dot_cs_end
			cp '"'
			jr nz, dot_cs_nq
			ld a, c
			xor 1
			ld c, a
			ld a, '"'
dot_cs_nq:
			cp ':'
			jr nz, dot_cs_st
			bit 0, c
			jr z, dot_cs_end		; a ':' outside quotes ends the line
dot_cs_st:
			ld (de), a
			inc hl
			inc de
			djnz dot_cs_lp
dot_cs_end:
			xor a
			ld (de), a
			ret

; dot_os - HL = a routine (in this 8K) to run on BASIC's side: BASIC's stack,
; IY = ERR_NR (the ROM's), interrupts on (the ROM's keyboard scan, "scroll?"),
; and - the Large Model - BASIC's memory in slots 2-7. Back with interrupts
; off, our stack (SP as it was) and our memory; A, BC, DE, HL as the routine
; left them, IX kept. Call it on the real stack, never with SP in the thread
dot_os:
			ld (dot_osp), sp
			ld (dot_oix), ix
	IFDEF NTC_ZXNDOTL
			ld sp, dot_xstack		; (the swap's calls: never on the program's stack, which is in a slot being swapped)
			push hl
			call dotl_bside			; slots 2-7 = BASIC's (ours noted)
			pop hl
	ENDIF
			ld sp, (dot_bsp)
			ld iy, #5C3A
			im 1					; the ROM's handler while the ROM runs
			ex de, hl
			ld hl, (#5C78)			; FRAMES now: its advance during the call is added to dot_frames
			ld (dot_fr0), hl
			ex de, hl
			ld de, dot_os_back
			push de
			ei
			jp (hl)
dot_os_back:
			di
			push af					; (the routine's result: A and the flags - dotl_alloc's carry)
			push hl
			push de
			ld hl, (#5C78)
			ld de, (dot_fr0)
			or a
			sbc hl, de
			ld de, (dot_frames)
			add hl, de
			ld (dot_frames), hl
			pop de
			pop hl
			pop af
	IFDEF NTC_ZXNDOTL
			ld sp, dot_xstack
			push af
			push hl
			call dotl_oside			; slots 2-7 = ours again
			pop hl
			pop af
	ENDIF
			im 2
			ld sp, (dot_osp)
			ld ix, (dot_oix)
			ret

; ---- the BASIC-side routines (reached through dot_os only)
; dot_chan - the upper screen, channel 2, is the channel rst #10 prints to
dot_chan:
			ld a, 2
			rst #18
			dw #1601				; CHAN-OPEN
			ret
; dot_putc - (dot_ch) printed
dot_putc:
			ld a, (dot_ch)
			rst #10
			ret
; dot_cls - the ROM's CLS, then the channel again (CLS leaves the lower screen's)
dot_cls:
			rst #18
			dw #0D6B				; CLS
			jr dot_chan
; dot_at - AT (dot_row), (dot_col): the ROM's control code 22
dot_at:
			ld a, 22
			rst #10
			ld a, (dot_row)
			rst #10
			ld a, (dot_col)
			rst #10
			ret
; dot_wait - a frame: until the ROM's interrupt moves FRAMES on (not halt: a program
; that stops on halt can't be stepped by every harness - and the ROM's handler runs
; the same either way)
dot_wait:
			ld hl, #5C78			; FRAMES
			ld a, (hl)
dot_wt_lp:
			cp (hl)
			jr z, dot_wt_lp
			ret
; dot_kread - a frame's wait for the ROM's keyboard scan, then A = the new key
; (LAST_K, the FLAGS bit cleared) or 0
dot_kread:
			call dot_wait
			ld a, (#5C3B)			; FLAGS: bit 5 = a new key in LAST_K
			bit 5, a
			jr z, dot_kr_none
			res 5, a
			ld (#5C3B), a
			ld a, (#5C08)			; LAST_K
			ret
dot_kr_none:
			xor a
			ret

; ---- the entry's data
dot_bsp:		dw 0			; BASIC's SP at entry
dot_hl:			dw 0			; HL at entry: the arguments
dot_bc:			dw 0			; BC at entry: the whole command line
dot_osp:		dw 0			; dot_os: our SP
dot_oix:		dw 0			; dot_os: IX
dot_ch:			db 0			; the character for dot_putc
dot_row:		db 0			; dot_at: row, column (0 based)
dot_col:		db 0
dot_frames:		dw 0			; frames counted (dot_irq, plus FRAMES' advance in the ROM calls): Ticks
dot_fr0:		dw 0			; dot_os: FRAMES at the call's start
dot_iold:		db 0			; BASIC's I register
ntc_cmdbuf:		ds 128			; the arguments, 0 ended (System.CommandLine)
; dot_irq - the IM 2 handler: a frame counted. Only this 8K is touched (it runs with the
; program's memory in the slots and SP on the program's real stack)
dot_irq:
			push hl
			ld hl, (dot_frames)
			inc hl
			ld (dot_frames), hl
			pop hl
			ei
			reti
; the IM 2 vector table, 256-aligned: the Z80 reads its bytes #FF and #100 (the data bus
; gives #FF) - the handler's address; the rest is the entry's two stacks
			ALIGN 256
dot_ivec:
			ds 255 - 48
			ds 32
dot_tstack:						; the entry's own stack (32 bytes: the entry's calls only)
			ds 16
dot_xstack:						; dot_os's own (16 bytes: the slot swap's calls - the Large Model) = dot_ivec + #FF
			dw dot_irq				; the vector

	IFDEF NTC_ZXNDOTL
; ------------------------------------------------------------
; The Large Model (zxndotl): the program runs from #8000 in four 8K pages of
; its own, the Memory class's window #4000-#7FFF is two more, all allocated
; from NextZXOS (IDE_BANK through M_P3DOS) at entry and given back at the end;
; its banks (64K: 8 pages each) come from the same allocator at the Memory
; class's first call (ntc_lib_dot.asm). Slots 2-7 hold ours while the program
; runs, BASIC's while a ROM / esxDOS call runs (dot_os: dotl_bside / dotl_oside).
; The program itself is read from this file, after its first 8K (M_GETHANDLE:
; NextZXOS leaves the file open there), into #8000 on.
; ------------------------------------------------------------
DOTL_MAXPG	equ 6 + 8 * 16			; pages at most: the 6 base ones and 16 banks (1MB)
dotl_bslots:	ds 6			; BASIC's pages in slots 2-7 (NextRegs #52-#57 at entry)
dotl_oslots:	ds 6			; ours (slots 2-3 the window, 4-7 the program #8000-#FFFF), as last seen
dotl_scr:		ds 6			; (dotl_oside's reads)
dotl_npages:	db 0			; pages allocated (in dotl_pages)
dotl_pages:		ds DOTL_MAXPG	; their numbers: the 6 base ones, then the Memory class's 8 a bank
dotl_e:			db 0			; dotl_alloc: the page it got / dotl_free: the page to give back
dotl_hdl:		db 0			; this file's handle
dotl_err:		dw 0			; the message for the error return

; dotl_setup - (the entry, on dot_tstack, BASIC's memory) BASIC's slots noted, the 6
; base pages allocated and mapped, the program read into #8000 on. Doesn't return when
; it fails: the error return to BASIC with a message
dotl_setup:
			ld hl, dotl_bslots		; BASIC's pages in slots 2-7
			ld d, #52
dotl_su_rd:
			ld bc, #243B
			out (c), d
			inc b
			in a, (c)
			ld (hl), a
			inc hl
			inc d
			ld a, d
			cp #58
			jr nz, dotl_su_rd
			ld b, 6					; the 6 base pages
dotl_su_al:
			push bc
			call dotl_page			; one more into dotl_pages
			pop bc
			jr nc, dotl_su_nomem
			djnz dotl_su_al
			ld hl, dotl_pages		; ours: slots 2-3 pages 0, 1 (the window), 4-7 pages 2-5
			ld de, dotl_oslots
			ld bc, 6
			ldir
			call dotl_oside			; mapped (this 8K and the ROM stay: slots 0, 1)
			rst #08
			db #8D					; M_GETHANDLE: A = this file's handle, open after its first 8K
			ld (dotl_hdl), a
			ld hl, #8000
			ld bc, ntc_end - #8000	; the program (the file's end: no window data, no Skip on this platform)
			push bc
			rst #08
			db #9D					; F_READ: A = handle, HL = where, BC = how many
			pop hl
			jr c, dotl_su_short
			or a
			sbc hl, bc				; all of it?
			ret z
dotl_su_short:
			ld hl, dotl_m_short
			jr dotl_fail
dotl_su_nomem:
			ld hl, dotl_m_nomem
; dotl_fail - HL = the message (bit 7 on its last character): the pages back, BASIC's
; memory and stack, the esxDOS custom error return (carry set, A = 0, HL = the message)
dotl_fail:
			ld (dotl_err), hl
			call dotl_freeall
			call dotl_bside
			ld sp, (dot_bsp)
			ld hl, (dotl_err)
			ld iy, #5C3A
			xor a
			scf
			ei
			ret
; dotl_exit - (End: ntc_plat_exit jumps here - this 8K stays mapped when slots 2-7 go
; back to BASIC's; the program's code doesn't) the pages given back, BASIC's memory and
; stack, carry clear (0 OK), interrupts on
dotl_exit:
			ld sp, dot_tstack
			call dotl_freeall
			call dotl_bside
			ld sp, (dot_bsp)
			ld iy, #5C3A
			ld a, (dot_iold)
			ld i, a
			im 1
			or a
			ei
			ret
dotl_m_nomem:	db "Out of memory: no free 8K pages (IDE_BANK", ')' + #80
dotl_m_short:	db "The .DOT file is short: the program did not read in ful", 'l' + #80

; dotl_page - one page allocated (IDE_BANK, on BASIC's side) into dotl_pages: C = its
; number, carry set; carry clear when there is none (or no room in dotl_pages)
dotl_page:
			ld a, (dotl_npages)
			cp DOTL_MAXPG
			ret nc					; (carry clear: full)
			ld hl, dotl_alloc
			call dot_os				; carry set = got one, (dotl_e) = it
			ret nc
			ld hl, dotl_pages
			ld a, (dotl_npages)
			ld e, a
			ld d, 0
			add hl, de
			ld a, (dotl_e)
			ld (hl), a
			ld c, a
			ld a, (dotl_npages)
			inc a
			ld (dotl_npages), a
			scf
			ret
; dotl_freeall - every page in dotl_pages given back (IDE_BANK free, on BASIC's side)
dotl_freeall:
			ld a, (dotl_npages)
			or a
			ret z
			ld b, a
			ld hl, dotl_pages
dotl_fa_lp:
			ld a, (hl)
			ld (dotl_e), a
			push bc
			push hl
			ld hl, dotl_free
			call dot_os
			pop hl
			pop bc
			inc hl
			djnz dotl_fa_lp
			xor a
			ld (dotl_npages), a
			ret

; dotl_bside - slots 2-7 = BASIC's pages, ours noted first (dotl_oslots)
; dotl_oside - slots 2-7 = ours again
; (from code in this 8K, on a stack in it: slots 2-7 change under anything else)
dotl_bside:
			ld hl, dotl_oslots
			ld ix, dotl_bslots
			jr dotl_swap
dotl_oside:
			ld hl, dotl_scr
			ld ix, dotl_oslots
dotl_swap:
			ld d, #52
dotl_sw_lp:
			ld bc, #243B
			out (c), d
			inc b
			in a, (c)				; the page there now
			ld (hl), a
			ld a, (ix + 0)
			out (c), a				; the page to be
			inc hl
			inc ix
			inc d
			ld a, d
			cp #58
			jr nz, dotl_sw_lp
			ret

; ---- BASIC-side (dot_os): the allocator, M_P3DOS's IDE_BANK (#01BD): H = 0 a ZX 8K
; page, L = 1 allocate / 3 free (E = the page), the call's registers in the alternate
; set; carry SET = done, E = the page
dotl_alloc:
			ld hl, #0001
			exx
			ld de, #01BD
			ld c, 7
			rst #08
			db #94					; M_P3DOS
			ld a, e
			ld (dotl_e), a
			ret
dotl_free:
			ld a, (dotl_e)
			ld e, a
			ld hl, #0003
			exx
			ld de, #01BD
			ld c, 7
			rst #08
			db #94
			ret

; (only when the program's own code names dot_fs_...: NTC_DOT_FS, set by the compiler - 20261116-4)
	IFDEF NTC_DOT_FS
; ---- esxDOS file calls for a FileSystem class (the Large Model): dot_fs_call runs on BASIC's
; side (HL = dot_fs_call : call dot_os) - NextZXOS pages its own RAM over #C000-#FFFF and reads
; BASIC's system variables during a call, so the call's stack, the name and the data must not be
; in the program's pages: the name goes in dot_fs_name, a stat buffer is dot_fs_stat, file data
; goes through dot_fs_data (256 bytes a call), all in this 8K, which is in both maps - in the
; buffer Option Buffer address, size puts there (20261116-5: they were 336 bytes of their own).
; In: dot_fs_hook (F_OPEN ...), dot_fs_a, dot_fs_bc, dot_fs_de, dot_fs_hl (HL and IX: NextZXOS
; reads a name's pointer from HL, esxDOS from IX). Out: dot_fs_a, dot_fs_bc, dot_fs_de,
; dot_fs_cy (1 = carry: an error, A its code)
dot_fs_call:
			ld a, (dot_fs_hook)
			ld (dot_fs_hk), a
			ld bc, (dot_fs_bc)
			ld de, (dot_fs_de)
			ld hl, (dot_fs_hl)
			push hl
			pop ix
			ld a, (dot_fs_a)
			rst #08
dot_fs_hk:	db 0
			ld (dot_fs_bc), bc
			ld (dot_fs_de), de
			ld (dot_fs_a), a
			ld a, 0
			rla
			ld (dot_fs_cy), a
			ret
dot_fs_hook:	db 0
dot_fs_a:		db 0
dot_fs_cy:		db 0
dot_fs_bc:		dw 0
dot_fs_de:		dw 0
dot_fs_hl:		dw 0
; the name, the stat buffer and the data go in the library's buffer, which the program places
; in this 8K with Option Buffer address, size (336 bytes or more, after the DOT's own code)
dot_fs_name		equ ntc_dotfs_buf		; 64 bytes
dot_fs_stat		equ ntc_dotfs_buf + 64	; 16 bytes
dot_fs_data		equ ntc_dotfs_buf + 80	; 256 bytes
			ASSERT (NTC_BUFSIZE >= 336) && (ntc_dotfs_buf >= ntc_dot8k_end) && (ntc_dotfs_buf + 336 <= #4000), "dot_fs_call: its buffers are the Option Buffer buffer, which must be in the DOT's 8K, after its code - Option Buffer address, 336 (or more) with the address between the end of the 8K's code (ntc_dot8k_end: see the listing) and &H4000 - 336"
	ENDIF
	ENDIF

			ASSERT $ <= #4000, "the dot command's entry code and data must fit in #2000-#3FFF"
ntc_dot8k_end:			; the 8K's code and data end here: the rest of it (to #3FFF) is free - Option Buffer may be there
			ds #4000 - $			; the first 8K of the file, padded
			OPT -Wno-fileorg		; (the file goes on where the 8K ends: the org below is where the program runs, not a gap)
			org #8000			; the program: read into its own pages by the entry

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI, 3 ADM-3A, 4 Televideo (CP/M)
NTC_TERM_RT	equ 0		; 1: the program calls StdIO.SetTerminal (the terminal is chosen while it runs)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, 0		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 24: Cls
			dw kw_cls

			; 25: Print "VB self test 7"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 28: p.x = 3
			dw kw_ltov, 3, var_p_x

			; 29: p.y = 4
			dw kw_ltov, 4, var_p_y

			; 30: Chk Dist2(p), 25
			dw p_dist2_c, var_p_x, var_p_y
			dw kw_vtov, var_dist2_dist2, tmp0
			dw p_chk_c, tmp0, lit_25

			; 31: Grow p, 10
			dw p_grow_c, var_p_x, var_p_y, lit_10

			; 32: Chk p.x, 13
			dw p_chk_c, var_p_x, lit_13

			; 33: Chk p.y, 14
			dw p_chk_c, var_p_y, lit_14

			; 34: q = p
			dw kw_vtov, var_p_x, var_q_x
			dw kw_vtov, var_p_y, var_q_y

			; 35: NoGrow q
			dw p_nogrow_c, var_q_x, var_q_y

			; 36: Chk q.x, 13
			dw p_chk_c, var_q_x, lit_13

			; 37: b.name = "box"
			dw kw_strcpy, var_b_name, str1

			; 38: b.size.x = 300
			dw kw_ltov, 300, var_b_size_x

			; 39: b.size.y = 400
			dw kw_ltov, 400, var_b_size_y

			; 40: b.topleft.x = 1
			dw kw_ltov, 1, var_b_topleft_x

			; 41: SetArea b
			dw p_setarea_c, var_b_name, var_b_topleft_x, var_b_topleft_y, var_b_size_x, var_b_size_y, var_b_area

			; 42: Chk b.area \ 1000, 120
			dw kw_l_div, var_b_area, llit_1000, ltmp0
			dw kw_l_ltoi, ltmp0, tmp0
			dw p_chk_c, tmp0, lit_120

			; 43: ChkS b.name, "box!"
			dw p_chks_c, var_b_name, str2

			; 44: Chk b.topleft.x, 2
			dw p_chk_c, var_b_topleft_x, lit_2

			; 45: Chk Twice2(p), 49
			dw p_twice2_c, var_p_x, var_p_y
			dw kw_vtov, var_twice2_twice2, tmp0
			dw p_chk_c, tmp0, lit_49

			; 48: For i = 0 To 2
			dw kw_ztov, var_i
for1_t:

			; 49: For j = 0 To 3
			dw kw_ztov, var_j
for2_t:

			; 50: grid(i, j) = i * 10 + j
			dw kw_4x, var_i, tmp0
			dw kw_add, tmp0, var_j, tmp0
			dw kw_mulvl, var_i, 10, tmp1
			dw kw_add, tmp1, var_j, tmp1
			dw kw_aset, arr_grid, tmp0, tmp1

			; 51: Next
			dw kw_next1l_n, var_j, 3, for2_t
for2_e:

			; 52: Next
			dw kw_next1l_n, var_i, 2, for1_t
for1_e:

			; 53: Chk Corner(grid), 23
			dw p_corner_c, ad_arr_grid
			dw kw_vtov, var_corner_corner, tmp0
			dw p_chk_c, tmp0, lit_23

			; 54: Chk Sum2(grid), 0 + 1 + 2 + 3 + 10 + 11 + 12 + 13 + 20 + 21 + 22 + 23
			dw p_sum2_c, ad_arr_grid
			dw kw_vtov, var_sum2_sum2, tmp0
			dw p_chk_c, tmp0, lit_138

			; 55: Chk Cols(grid), 3
			dw p_cols_c, ad_arr_grid
			dw kw_vtov, var_cols_cols, tmp0
			dw p_chk_c, tmp0, lit_3

			; 56: Clear2 grid
			dw p_clear2_c, ad_arr_grid

			; 57: Chk grid(2, 3), 0
			dw p_chk_c, arr_grid+22, lit_0

			; 60: w = &H12345678
			dw kw_l_mov, llit_305419896, var_w

			; 61: ChkS Hex$(w), "12345678"
			dw kw_l_hex, stmp0, var_w
			dw p_chks_c, stmp0, str3

			; 62: w = -1
			dw kw_l_mov, llit_m1, var_w

			; 63: ChkS Hex$(w), "FFFFFFFF"
			dw kw_l_hex, stmp0, var_w
			dw p_chks_c, stmp0, str4

			; 64: w = 0
			dw kw_l_mov, llit_0, var_w

			; 65: i = 2
			dw kw_ltov, 2, var_i

			; 67: For k = 1 To 10 Step i
			dw kw_l_mov, llit_1, var_k
			dw kw_l_itol, var_i, for3_s
			dw kw_l_cplt, for3_s, llit_0
			dw kw_goto_iftrue_n, for3_n
			dw kw_l_cpgt, var_k, llit_10
			dw kw_goto_iftrue_n, for3_e
			dw for3_t_go
for3_n:
			dw kw_l_cplt, var_k, llit_10
			dw kw_goto_iftrue_n, for3_e
for3_t:

			; 68: w = w + k
			dw kw_l_add, var_w, var_k, var_w

			; 69: Next
			dw kw_l_add, var_k, for3_s, var_k
			dw kw_l_cplt, for3_s, llit_0
			dw kw_goto_iftrue_n, for3_m
			dw kw_l_cple, var_k, llit_10
			dw kw_goto_iftrue_n, for3_t
			dw for3_e_go
for3_m:
			dw kw_l_cpge, var_k, llit_10
			dw kw_goto_iftrue_n, for3_t
for3_e:

			; 70: Chk w, 25
			dw kw_l_ltoi, var_w, tmp0
			dw p_chk_c, tmp0, lit_25

			; 71: For k = 10 To 1 Step -i
			dw kw_l_mov, llit_10, var_k
			dw kw_negv, var_i, tmp0
			dw kw_l_itol, tmp0, for4_s
			dw kw_l_cplt, for4_s, llit_0
			dw kw_goto_iftrue_n, for4_n
			dw kw_l_cpgt, var_k, llit_1
			dw kw_goto_iftrue_n, for4_e
			dw for4_t_go
for4_n:
			dw kw_l_cplt, var_k, llit_1
			dw kw_goto_iftrue_n, for4_e
for4_t:

			; 72: w = w + k
			dw kw_l_add, var_w, var_k, var_w

			; 73: Next
			dw kw_l_add, var_k, for4_s, var_k
			dw kw_l_cplt, for4_s, llit_0
			dw kw_goto_iftrue_n, for4_m
			dw kw_l_cple, var_k, llit_1
			dw kw_goto_iftrue_n, for4_t
			dw for4_e_go
for4_m:
			dw kw_l_cpge, var_k, llit_1
			dw kw_goto_iftrue_n, for4_t
for4_e:

			; 74: Chk w, 55
			dw kw_l_ltoi, var_w, tmp0
			dw p_chk_c, tmp0, lit_55

			; 76: Print
			dw kw_printnl

			; 77: Print t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printstrvar, str5
			dw kw_printint, var_bad
			dw kw_printstrvar, str6
			dw kw_printnl

			; 78: End
			dw kw_printnl0
			dw kw_printstrvar, str7
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub chk (normal mode)
; ============================================================

p_chk:

			; 81: t = t + 1
			dw kw_inc, var_t

			; 82: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str8

			; 83: If got = want Then
			dw kw_cpeqvv, var_chk_got, var_chk_want
			dw kw_goto_iffalse_n, if5_1

			; 84: Print "ok ";
			dw kw_printstrvar, str9

			; 85: Else
			dw if5_e_go
if5_1:

			; 86: Print "FAIL("; got; ") ";
			dw kw_printstrvar, str10
			dw kw_printint, var_chk_got
			dw kw_printstrvar, str11

			; 87: bad = bad + 1
			dw kw_inc, var_bad

			; 88: End If
if5_e:
			dw p_chk_r

; ============================================================
; sub chks (normal mode)
; ============================================================

p_chks:

			; 92: t = t + 1
			dw kw_inc, var_t

			; 93: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str8

			; 94: If got = want Then
			dw kw_strcmpeq, var_chks_got, var_chks_want
			dw kw_goto_iffalse_n, if6_1

			; 95: Print "ok ";
			dw kw_printstrvar, str9

			; 96: Else
			dw if6_e_go
if6_1:

			; 97: Print "FAIL["; got; "] ";
			dw kw_printstrvar, str12
			dw kw_printstrvar, var_chks_got
			dw kw_printstrvar, str13

			; 98: bad = bad + 1
			dw kw_inc, var_bad

			; 99: End If
if6_e:
			dw p_chks_r

; ============================================================
; function dist2 (normal mode)
; ============================================================

p_dist2:

			; 103: Dist2 = a.x * a.x + a.y * a.y
			dw kw_mulvv, var_dist2_a_x, var_dist2_a_x, tmp0
			dw kw_mulvv, var_dist2_a_y, var_dist2_a_y, tmp1
			dw kw_add, tmp0, tmp1, var_dist2_dist2
			dw p_dist2_r

; ============================================================
; sub grow (normal mode)
; ============================================================

p_grow:

			; 107: a.x = a.x + n
ntc_rf1:
			dw kw_add, 0, var_grow_n, 0

			; 108: a.y = a.y + n
ntc_rf2:
			dw kw_add, 0, var_grow_n, 0
			dw p_grow_r

; ============================================================
; sub nogrow (normal mode)
; ============================================================

p_nogrow:

			; 112: a.x = 0
			dw kw_ztov, var_nogrow_a_x
			dw p_nogrow_r

; ============================================================
; sub setarea (normal mode)
; ============================================================

p_setarea:

			; 117: bx.area = CLng(bx.size.x) * bx.size.y
ntc_rf3:
			dw kw_l_itol, 0, ltmp0
ntc_rf4:
			dw kw_l_itol, 0, ltmp1
ntc_rf5:
			dw kw_l_mul, ltmp0, ltmp1, 0

			; 118: bx.name = bx.name & "!"
ntc_rf6:
			dw kw_strcat, 0, str14

			; 119: Grow bx.topleft, 1
ntc_rf7:
			dw p_grow_c, 0, 0, lit_1
			dw p_setarea_r

; ============================================================
; function twice2 (normal mode)
; ============================================================

p_twice2:

			; 124: Twice2 = Dist2(a) \ 10 + a.x
ntc_rf8:
			dw p_dist2_c, 0, 0
			dw kw_vtov, var_dist2_dist2, tmp0
			dw kw_divvl, tmp0, 10, tmp0
ntc_rf9:
			dw kw_add, tmp0, 0, var_twice2_twice2
			dw p_twice2_r

; ============================================================
; function corner (normal mode)
; ============================================================

p_corner:

			; 128: Corner = g(2, 3)
			dw kw_pget2, pa_corner_g, lit_2, lit_3, var_corner_corner
			dw p_corner_r

; ============================================================
; function sum2 (normal mode)
; ============================================================

p_sum2:

			; 132: Dim r As Integer, c As Integer

			; 133: Sum2 = 0
			dw kw_ztov, var_sum2_sum2

			; 134: For r = LBound(g, 1) To UBound(g, 1)
			dw kw_lbound, pa_sum2_g, var_sum2_r
			dw kw_ubound, pa_sum2_g, for7_l
			dw kw_forupv_n, var_sum2_r, for7_l, for7_e
for7_t:

			; 135: For c = LBound(g, 2) To UBound(g, 2)
			dw kw_lbound, pa_sum2_g+2, var_sum2_c
			dw kw_ubound, pa_sum2_g+2, for8_l
			dw kw_forupv_n, var_sum2_c, for8_l, for8_e
for8_t:

			; 136: Sum2 = Sum2 + g(r, c)
			dw kw_pget2, pa_sum2_g, var_sum2_r, var_sum2_c, tmp1
			dw kw_add, var_sum2_sum2, tmp1, var_sum2_sum2

			; 137: Next
			dw kw_next1v_n, var_sum2_c, for8_l, for8_t
for8_e:

			; 138: Next
			dw kw_next1v_n, var_sum2_r, for7_l, for7_t
for7_e:
			dw p_sum2_r

