p_cols:

			; 142: Cols = UBound(g, 2)
			dw kw_ubound, pa_cols_g+2, var_cols_cols
			dw p_cols_r

; ============================================================
; sub clear2 (normal mode)
; ============================================================

p_clear2:

			; 146: Dim r As Integer, c As Integer

			; 147: For r = 0 To UBound(g, 1)
			dw kw_ztov, var_clear2_r
			dw kw_ubound, pa_clear2_g, for9_l
			dw kw_forupv_n, var_clear2_r, for9_l, for9_e
for9_t:

			; 148: For c = 0 To UBound(g, 2)
			dw kw_ztov, var_clear2_c
			dw kw_ubound, pa_clear2_g+2, for10_l
			dw kw_forupv_n, var_clear2_c, for10_l, for10_e
for10_t:

			; 149: g(r, c) = 0
			dw kw_pset2, pa_clear2_g, var_clear2_r, var_clear2_c, lit_0

			; 150: Next
			dw kw_next1v_n, var_clear2_c, for10_l, for10_t
for10_e:

			; 151: Next
			dw kw_next1v_n, var_clear2_r, for9_l, for9_t
for9_e:
			dw p_clear2_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

for3_t_go:			ld sp, for3_t
			jp ntc_xn
for3_e_go:			ld sp, for3_e
			jp ntc_xn
for4_t_go:			ld sp, for4_t
			jp ntc_xn
for4_e_go:			ld sp, for4_e
			jp ntc_xn
if5_e_go:			ld sp, if5_e
			jp ntc_xn
if6_e_go:			ld sp, if6_e
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld de, var_chk_got		; (the block of 2 parameters)
			ldi
			ldi
			pop hl			; want
			ldi
			ldi
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_chks_c:		; call chks (normal)
			pop hl			; got
			ld de, var_chks_got
			ld b, 40
p_chks_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si0_e
			inc hl
			inc de
			djnz p_chks_si0
			xor a
			ld (de), a
p_chks_si0_e:
			pop hl			; want
			ld de, var_chks_want
			ld b, 40
p_chks_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si1_e
			inc hl
			inc de
			djnz p_chks_si1
			xor a
			ld (de), a
p_chks_si1_e:
			ld (p_chks_rs), sp
			ld sp, p_chks
			jp ntc_xn
p_chks_r:		; end of chks
			ld sp, (p_chks_rs)
			jp ntc_xn
p_dist2_c:		; call dist2 (normal)
			pop hl			; a.x
			ld de, var_dist2_a_x
			ld bc, 2
			ldir
			pop hl			; a.y
			ld de, var_dist2_a_y
			ld bc, 2
			ldir
			ld hl, 0
			ld (var_dist2_dist2), hl
			ld (p_dist2_rs), sp
			ld sp, p_dist2
			jp ntc_xn
p_dist2_r:		; end of dist2
			ld sp, (p_dist2_rs)
			jp ntc_xn
p_grow_c:		; call grow (normal)
			pop hl			; a.x
			ld (ntc_rf1 + 2), hl		; (by reference: var_grow_a_x)
			ld (ntc_rf1 + 6), hl		; (by reference: var_grow_a_x)
			pop hl			; a.y
			ld (ntc_rf2 + 2), hl		; (by reference: var_grow_a_y)
			ld (ntc_rf2 + 6), hl		; (by reference: var_grow_a_y)
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_grow_n), de
			ld (p_grow_rs), sp
			ld sp, p_grow
			jp ntc_xn
p_grow_r:		; end of grow
			ld sp, (p_grow_rs)
			jp ntc_xn
p_nogrow_c:		; call nogrow (normal)
			pop hl			; a.x
			ld de, var_nogrow_a_x
			ld bc, 2
			ldir
			pop hl			; a.y
			ld de, var_nogrow_a_y
			ld bc, 2
			ldir
			ld (p_nogrow_rs), sp
			ld sp, p_nogrow
			jp ntc_xn
p_nogrow_r:		; end of nogrow
			ld sp, (p_nogrow_rs)
			jp ntc_xn
p_setarea_c:		; call setarea (normal)
			pop hl			; bx.name
			ld (ntc_rf6 + 2), hl		; (by reference: var_setarea_bx_name)
			pop hl			; bx.topleft.x
			ld (ntc_rf7 + 2), hl		; (by reference: var_setarea_bx_topleft_x)
			pop hl			; bx.topleft.y
			ld (ntc_rf7 + 4), hl		; (by reference: var_setarea_bx_topleft_y)
			pop hl			; bx.size.x
			ld (ntc_rf3 + 2), hl		; (by reference: var_setarea_bx_size_x)
			pop hl			; bx.size.y
			ld (ntc_rf4 + 2), hl		; (by reference: var_setarea_bx_size_y)
			pop hl			; bx.area
			ld (ntc_rf5 + 6), hl		; (by reference: var_setarea_bx_area)
			ld (p_setarea_rs), sp
			ld sp, p_setarea
			jp ntc_xn
p_setarea_r:		; end of setarea
			ld sp, (p_setarea_rs)
			jp ntc_xn
p_twice2_c:		; call twice2 (normal)
			pop hl			; a.x
			ld (ntc_rf8 + 2), hl		; (by reference: var_twice2_a_x)
			ld (ntc_rf9 + 4), hl		; (by reference: var_twice2_a_x)
			pop hl			; a.y
			ld (ntc_rf8 + 4), hl		; (by reference: var_twice2_a_y)
			ld hl, 0
			ld (var_twice2_twice2), hl
			ld (p_twice2_rs), sp
			ld sp, p_twice2
			jp ntc_xn
p_twice2_r:		; end of twice2
			ld sp, (p_twice2_rs)
			jp ntc_xn
p_corner_c:		; call corner (normal)
			pop hl			; g() descriptor
			ld de, pa_corner_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_corner_corner), hl
			ld (p_corner_rs), sp
			ld sp, p_corner
			jp ntc_xn
p_corner_r:		; end of corner
			ld sp, (p_corner_rs)
			jp ntc_xn
p_sum2_c:		; call sum2 (normal)
			pop hl			; g() descriptor
			ld de, pa_sum2_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_sum2_sum2), hl
			ld (var_sum2_r), hl
			ld (var_sum2_c), hl
			ld (p_sum2_rs), sp
			ld sp, p_sum2
			jp ntc_xn
p_sum2_r:		; end of sum2
			ld sp, (p_sum2_rs)
			jp ntc_xn
p_cols_c:		; call cols (normal)
			pop hl			; g() descriptor
			ld de, pa_cols_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_cols_cols), hl
			ld (p_cols_rs), sp
			ld sp, p_cols
			jp ntc_xn
p_cols_r:		; end of cols
			ld sp, (p_cols_rs)
			jp ntc_xn
p_clear2_c:		; call clear2 (normal)
			pop hl			; g() descriptor
			ld de, pa_clear2_g
			ld bc, 12
			ldir
			ld hl, 0
			ld (var_clear2_r), hl
			ld (var_clear2_c), hl
			ld (p_clear2_rs), sp
			ld sp, p_clear2
			jp ntc_xn
p_clear2_r:		; end of clear2
			ld sp, (p_clear2_rs)
			jp ntc_xn

